import 'package:flutter/material.dart';import 'package:get/get.dart';import '../controllers/auth_controller.dart';
class RegisterPage extends StatefulWidget {const RegisterPage({super.key});@override State<RegisterPage> createState()=>_RegisterPageState();}
class _RegisterPageState extends State<RegisterPage>{final f=<String,TextEditingController>{for(final k in ['name','email','phone','password','license','make','model','color','plate'])k:TextEditingController()};String vehicleType='car';Widget field(String k,String label,{bool secret=false})=>Padding(padding:const EdgeInsets.only(bottom:12),child:TextField(controller:f[k],obscureText:secret,decoration:InputDecoration(labelText:label)));
@override Widget build(BuildContext context){final c=Get.find<AuthController>();final driver=c.selectedRole.value=='driver';return Scaffold(appBar:AppBar(title:Text('Chalo Bhai • Create ${driver?'Driver':'User'} Account')),body:ListView(padding:const EdgeInsets.all(20),children:[field('name','Full name'),field('email','Email'),field('phone','Phone'),field('password','Password',secret:true),if(driver)...[field('license','Driving licence number'),field('make','Vehicle make'),field('model','Vehicle model'),field('color','Vehicle color'),field('plate','Plate number'),DropdownButtonFormField(value:vehicleType,items:['bike','auto','car','suv'].map((v)=>DropdownMenuItem(value:v,child:Text(v.toUpperCase()))).toList(),onChanged:(v)=>setState(()=>vehicleType=v!),decoration:const InputDecoration(labelText:'Vehicle type')),const SizedBox(height:12)],Obx(()=>FilledButton(onPressed:c.loading.value?null:(){if(driver){c.registerDriver(name:f['name']!.text,email:f['email']!.text,phone:f['phone']!.text,password:f['password']!.text,license:f['license']!.text,make:f['make']!.text,model:f['model']!.text,color:f['color']!.text,plate:f['plate']!.text,vehicleType:vehicleType);}else{c.registerUser(name:f['name']!.text,email:f['email']!.text,phone:f['phone']!.text,password:f['password']!.text);}},child:Text(c.loading.value?'Creating...':'Create account')))]));}}
